      msgs: [
        {
          from: ME,
          to: [P.rachel],
          cc: [P.elena],
          at: at(5, 20),
          body: `Rachel, Thursday at 3 PM works. Could you send a dial-in? I'd like to focus on §7.2 and §11 first.\n\nThanks,\nAvery`,
        },
