          ref={inputRef}
          className="searchbar__input"
          type="text"
          value={value}
          placeholder="Search mail"
          aria-label="Search mail"
          autoComplete="off"
          spellCheck={false}
          onFocus={() => {
            setOpen(true);
            setAdvanced(false);
          }}
