              <User size={14} /> Tip: use <code>from:</code>, <code>label:</code>, <code>has:attachment</code>, <code>before:2026/09/01</code>
            </div>
          ) : null}
        </div>
      ) : null}

      {advanced ? (
        <form
          className="searchbar__advanced"
          onSubmit={(e) => {
            e.preventDefault();
            run(buildQuery(adv));
          }}
        >
