            </label>
          ))}
          <label className="adv-row">
            <span>Size greater than</span>
            <input value={adv.larger} placeholder="e.g. 1M" onChange={(e) => setAdv({ ...adv, larger: e.target.value })} />
          </label>
          <label className="adv-row">
