            </button>
            <button type="submit" className="btn btn--primary">
              Search
            </button>
          </div>
        </form>
      ) : null}
    </div>
  );
}

export function applyQuickFilter(query: string, token: string): string {
  if (token.startsWith('newer_than:')) return setKeyToken(query, 'newer_than', hasToken(query, token) ? null : token);
  return toggleToken(query, token);
}

export { tokenize };

