+
+  useEffect(() => () => {
+    clearTimeout(saveTimer.current);
+    flush();
+  }, [flush]);
+
+  useEffect(() => {
+    if (!draft) return;
+    if (draft.cc.length) setShowCc(true);
+    if (draft.bcc.length) setShowBcc(true);
+    // eslint-disable-next-line react-hooks/exhaustive-deps
