+              <MenuList
+                onClose={() => setMore(false)}
+                items={[
+                  { label: variant === 'full' ? 'Exit full screen' : 'Full screen', onClick: () => useUI.getState().updateWin(draftId, { maximized: variant !== 'full' }) },
