    <div
      role="row"
      data-draft-id={d.id}
      className={`row is-read row--draft ${selected ? 'is-selected' : ''}`}
      onClick={(e) => (e.metaKey || e.ctrlKey || e.shiftKey || (mobile && useUI.getState().selected.length) ? onSelect(d.id, e) : openDraftItem(d.id))}
