  --text: #1f1f1f;
  --text-2: #444746;
  --text-3: #5f6368;
  --text-4: #80868b;
  --border: #dadce0;
  --border-strong: #c4c7c5;
  --border-soft: #eceef1;
  --hover: rgba(31, 31, 31, 0.07);
  --hover-strong: rgba(31, 31, 31, 0.12);
  --search-bg: #e9eef6;
  --danger: #b3261e;
  --danger-soft: #fce8e6;
  --star: #f4b400;
  --warn-bg: #fef7e0;
  --warn-fg: #7a5200;
  --ok: #188038;
  --mark: #fff0a6;
  --toast-bg: #303030;
  --toast-fg: #f2f2f2;
  --toast-action: #a8c7fa;
  --compose-head: #f2f6fc;
  --on-accent: #ffffff;

  --accent: #0b57d0;
  --accent-container: color-mix(in srgb, var(--accent) 17%, var(--surface));
  --accent-soft: color-mix(in srgb, var(--accent) 9%, transparent);
  --on-container: color-mix(in srgb, var(--accent) 55%, #000);
  --compose-bg: color-mix(in srgb, var(--accent) 22%, var(--surface));
  --row-selected: color-mix(in srgb, var(--accent) 20%, var(--surface));

  --shadow-1: 0 1px 2px rgba(60, 64, 67, 0.3), 0 1px 3px 1px rgba(60, 64, 67, 0.15);
  --shadow-2: 0 2px 6px 2px rgba(60, 64, 67, 0.15), 0 1px 2px rgba(60, 64, 67, 0.3);
  --shadow-3: 0 8px 10px 1px rgba(0, 0, 0, 0.14), 0 3px 14px 2px rgba(0, 0, 0, 0.12), 0 5px 5px -3px rgba(0, 0, 0, 0.2);

  --radius-panel: 16px;
