.searchbar__item.is-active { background: var(--hover); }
.searchbar__icon { display: inline-flex; color: var(--text-3); flex: none; }
.searchbar__primary { flex: 0 1 auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.searchbar__secondary { flex: 1 1 0; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-3); font-size: 13px; }
.searchbar__date { font-size: 12px; color: var(--text-3); flex: none; }
.searchbar__remove { margin-left: auto; font-size: 12px; color: var(--accent); font-weight: 600; opacity: 0; }
.searchbar__item:hover .searchbar__remove,
.searchbar__remove:focus-visible { opacity: 1; }
.searchbar__empty,
.searchbar__foot { padding: 8px 20px; font-size: 12px; color: var(--text-3); display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.searchbar__advanced { padding: 18px 22px 16px; display: flex; flex-direction: column; gap: 10px; }
.adv-row { display: grid; grid-template-columns: 150px 1fr; align-items: center; gap: 12px; font-size: 13px; color: var(--text-2); }
.adv-row input:not([type='checkbox']),
.adv-row select {
  height: 34px;
  padding: 0 4px;
  border: 0;
  border-bottom: 1px solid var(--border-strong);
  border-radius: 0;
  background: transparent;
  outline: 0;
  width: 100%;
}
.adv-row input:focus { border-bottom-color: var(--accent); box-shadow: 0 1px 0 var(--accent); }
.adv-check { display: inline-flex; align-items: center; gap: 6px; }
.adv-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 8px; }

/* ------------------------------------------------------------ sidebar */

.sidebar {
  width: var(--sidebar-w);
  flex: none;
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 4px 0 0 8px;
  transition: width 0.18s ease;
}
.compose-btn {
  display: flex;
  align-items: center;
  gap: 14px;
  align-self: flex-start;
  height: 56px;
  margin: 4px 0 16px 4px;
  padding: 0 24px 0 18px;
  border-radius: 16px;
  background: var(--compose-bg);
  color: var(--on-container);
  font-size: 14px;
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(60, 64, 67, 0.2);
  transition: box-shadow 0.15s;
}
.compose-btn:hover { box-shadow: 0 2px 6px rgba(60, 64, 67, 0.35); }
.sidebar__scroll { flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden; padding-bottom: 12px; padding-right: 8px; }
.nav-item {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  height: 32px;
  padding: 0 12px 0 26px;
  border-radius: 16px;
  color: var(--text);
  font-size: 14px;
  cursor: pointer;
  user-select: none;
}
.nav-item:hover { background: var(--hover); }
.nav-item__icon { display: inline-flex; flex: none; width: 20px; margin-right: 18px; color: var(--text-2); }
.nav-item__label { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nav-item__count { margin-left: 8px; font-size: 12px; color: var(--text-2); font-weight: 600; }
.nav-item.is-active { background: var(--accent-container); color: var(--on-container); font-weight: 700; }
.nav-item.is-active .nav-item__icon,
.nav-item.is-active .nav-item__count { color: var(--on-container); }
.nav-item.has-unread { font-weight: 700; }
.nav-item.is-drop { outline: 2px dashed var(--accent); outline-offset: -2px; background: var(--accent-soft); }
.nav-item--more:disabled { opacity: 0.6; }
.nav-item--label { padding: 0; }
.nav-item__link { display: flex; align-items: center; flex: 1; min-width: 0; height: 100%; padding-left: 26px; }
.nav-item__more {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  margin-right: 4px;
  border-radius: 50%;
  color: var(--text-2);
  opacity: 0;
}
.nav-item__more:hover { background: var(--hover-strong); }
.nav-item--label:hover .nav-item__more,
.nav-item__more:focus-visible { opacity: 1; }
.nav-item--label:hover .nav-item__count { display: none; }
.nav-item__dot { position: absolute; top: 4px; right: 12px; width: 8px; height: 8px; border-radius: 50%; background: var(--accent); }
.sidebar__heading { display: flex; align-items: center; justify-content: space-between; margin: 14px 0 2px; padding: 0 4px 0 26px; }
.sidebar__heading-btn { font-size: 14px; font-weight: 600; color: var(--text); }
.sidebar__collapsed-plus { align-self: center; margin: 8px 0; }
.sidebar__foot { padding: 12px 18px 16px; display: flex; flex-direction: column; gap: 6px; }
.sidebar__foot-text { font-size: 11px; color: var(--text-3); }

.sidebar.is-collapsed { width: 72px; padding-left: 8px; }
.sidebar.is-collapsed .compose-btn { width: 56px; padding: 0; justify-content: center; margin-left: 2px; }
.sidebar.is-collapsed .sidebar__scroll { padding-right: 8px; }
.sidebar.is-collapsed .nav-item { width: 56px; padding: 0; justify-content: center; height: 36px; margin: 0 auto 2px 2px; }
.sidebar.is-collapsed .nav-item__icon { margin: 0; }
.sidebar.is-collapsed .nav-item__link { padding: 0; justify-content: center; }

.scrim {
  position: fixed;
  inset: 0;
  z-index: 65;
  background: rgba(0, 0, 0, 0.42);
  animation: fade 0.2s;
}
.sidebar.is-drawer {
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 70;
  width: min(312px, 86vw);
  padding: 16px 0 0 12px;
  background: var(--surface);
  transform: translateX(-104%);
  transition: transform 0.24s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.24s;
  border-radius: 0 20px 20px 0;
  visibility: hidden;
}
.sidebar.is-drawer.is-open { transform: none; box-shadow: var(--shadow-3); visibility: visible; }
.sidebar.is-drawer .compose-btn { margin-left: 4px; }

/* ------------------------------------------------------------ main panel */

.main { flex: 1; min-width: 0; min-height: 0; padding: 0 16px 16px 0; display: flex; }
.panel {
  position: relative;
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border-radius: var(--radius-panel);
  overflow: hidden;
}
.panel__scroll { flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden; overscroll-behavior: contain; }
.panel--split { flex-direction: row; }
.split__list { flex: 0 0 clamp(400px, 38%, 540px); display: flex; flex-direction: column; min-width: 0; border-right: 1px solid var(--border-soft); }
.split__read { flex: 1; min-width: 0; display: flex; flex-direction: column; background: var(--surface); }
.panel--settings { overflow: auto; }

/* ------------------------------------------------------------ toolbar */

.toolbar {
  display: flex;
  align-items: center;
  gap: 2px;
  min-height: 52px;
  padding: 4px 8px 4px 12px;
  flex: none;
  border-bottom: 1px solid var(--border-soft);
  background: var(--surface);
}
.toolbar.has-selection { background: color-mix(in srgb, var(--accent) 5%, var(--surface)); }
.toolbar__group { display: flex; align-items: center; gap: 2px; min-width: 0; }
.toolbar__spacer { flex: 1; }
.toolbar__select { display: inline-flex; align-items: center; margin-right: 4px; }
.toolbar__caret { display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 32px; border-radius: 6px; color: var(--text-2); margin-left: -2px; }
.toolbar__caret:hover { background: var(--hover); }
.toolbar__sep { display: inline-block; width: 1px; height: 20px; margin: 0 6px; background: var(--border); flex: none; }
.toolbar__count { margin-left: 8px; font-size: 13px; color: var(--text-2); white-space: nowrap; }
.toolbar__range { margin-right: 8px; font-size: 12px; color: var(--text-3); white-space: nowrap; }
.toolbar--thread { padding-left: 8px; }

/* ------------------------------------------------------------ tabs */

.tabs { display: flex; flex: none; border-bottom: 1px solid var(--border-soft); overflow-x: auto; scrollbar-width: none; }
.tabs::-webkit-scrollbar { display: none; }
.tab {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  flex: 0 1 232px;
  min-width: 0;
  height: 56px;
  padding: 0 16px;
  color: var(--text-3);
  font-size: 14px;
  font-weight: 500;
  border-bottom: 3px solid transparent;
  white-space: nowrap;
}
.tab:hover { background: var(--hover); }
.tab__icon { display: inline-flex; flex: none; }
.tab__label { overflow: hidden; text-overflow: ellipsis; }
.tab__badge {
  padding: 1px 8px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--tab-color) 16%, transparent);
  color: var(--tab-color);
  font-size: 12px;
  font-weight: 600;
}
.tab.is-active { color: var(--tab-color); border-bottom-color: var(--tab-color); }
.tab.is-active .tab__icon { color: var(--tab-color); }
.tab.is-drop { background: var(--accent-soft); outline: 2px dashed var(--accent); outline-offset: -4px; }
.search-chips { display: flex; flex-wrap: wrap; gap: 8px; padding: 10px 16px; border-bottom: 1px solid var(--border-soft); flex: none; }

/* ------------------------------------------------------------ responsive shell */

@media (max-width: 960px) {
  .header__left { min-width: 0; }
  .main { padding: 0 8px 8px; }
}

@media (max-width: 700px) {
  :root { --header-h: 56px; }
  .header { padding: 0 4px; gap: 0; }
  .brand__title { font-size: 18px; }
  .brand { gap: 8px; padding-left: 0; }
  .icon-btn--lg { width: 44px; height: 44px; }
  .account-btn { width: 40px; height: 40px; margin-left: 2px; }
  .main { padding: 0; }
  .panel { border-radius: 20px 20px 0 0; }
  .toolbar { padding-left: 4px; padding-right: 4px; min-height: 48px; }
  .toolbar__range { display: none; }
  .toolbar__sep { margin: 0 2px; }
  .tab { flex: 1 1 auto; gap: 8px; padding: 0 12px; justify-content: center; }
  .tab:not(.is-active) .tab__label,
  .tab:not(.is-active) .tab__badge { display: none; }
  .tab.is-active { flex: 2 1 auto; }
  .tab__badge { display: none; }
  .search-chips { overflow-x: auto; flex-wrap: nowrap; }
  .searchbar--mobile .searchbar__panel,
  .searchbar--mobile .searchbar__advanced {
    position: fixed;
    top: var(--header-h);
    left: 0;
    right: 0;
    bottom: 0;
    max-height: none;
    border-radius: 0;
    border: 0;
    box-shadow: none;
    overflow: auto;
  }
  .adv-row { grid-template-columns: 1fr; gap: 2px; }
}

