args.streamContent:
.thread {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  min-width: 0;
}
.thread__scroll { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
.thread__inner { max-width: 1000px; margin: 0 auto; padding: 0 20px 56px; }
.thread__inner > .banner { margin: 0 -20px; }

.thread__head { display: flex; align-items: center; flex-wrap: wrap; gap: 8px 12px; padding: 18px 0 14px 52px; }
.thread__subject { font-size: 22px; font-weight: 400; line-height: 1.3; letter-spacing: -0.005em; color: var(--text); word-break: break-word; }
.thread__chips { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.thread__head-actions { margin-left: auto; }
.tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 20px;
  padding: 0 6px 0 8px;
  border-radius: 6px;
  background: var(--surface-3);
  color: var(--text-2);
  font-size: 12px;
  font-weight: 500;
}
.tag-chip button { font-size: 14px; line-height: 1; color: var(--text-3); padding: 0 2px; }
.tag-chip button:hover { color: var(--text); }
.tag-chip--imp { padding-right: 8px; }

.thread__messages { display: flex; flex-direction: column; }
.thread__pill {
  display: flex;
  align-items: center;
  gap: 10px;
  align-self: center;
  margin: 6px 0;
  padding: 6px 14px 6px 8px;
  border: 1px solid var(--border);
  border-radius: 18px;
  font-size: 13px;
  color: var(--text-2);
}
.thread__pill:hover { background: var(--hover); }
.thread__pill-count { display: inline-flex; align-items: center; justify-content: center; min-width: 22px; height: 22px; padding: 0 6px; border-radius: 11px; background: var(--accent); color: var(--on-accent); font-size: 12px; font-weight: 700; }

.msg { border-top: 1px solid var(--border-soft); padding: 16px 0 8px; }
.msg:first-child { border-top: 0; }
.msg--collapsed {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 8px;
  margin: 0 -8px;
  border-radius: 8px;
  cursor: pointer;
}
.msg--collapsed:hover { background: var(--hover); }
.msg--collapsed.is-unread .msg__from { font-weight: 700; }
.msg__from { flex: 0 0 180px; max-width: 34%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 500; }
.msg__snippet { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-3); }
.msg__att { font-size: 12px; color: var(--text-3); }
.msg__date { flex: none; font-size: 12px; color: var(--text-3); }

.msg__head { display: flex; align-items: flex-start; gap: 12px; }
.msg__avatar { flex: none; border-radius: 50%; margin-top: 2px; }
.msg__who { flex: 1; min-width: 0; cursor: pointer; }
.msg__name-line { display: flex; align-items: baseline; flex-wrap: wrap; gap: 2px 6px; }
.msg__name { font-weight: 600; font-size: 14px; }
.msg__email { font-size: 12px; color: var(--text-3); overflow: hidden; text-overflow: ellipsis; }
.msg__to-line { margin-top: 1px; }
.msg__to { display: inline-flex; align-items: center; gap: 2px; font-size: 12px; color: var(--text-3); padding: 1px 4px 1px 0; border-radius: 4px; }
.msg__to:hover { color: var(--text); }
.msg__tools { display: flex; align-items: center; gap: 0; flex: none; }
.msg__when { font-size: 12px; color: var(--text-3); margin-right: 6px; white-space: nowrap; }
.msg__content { padding: 4px 0 0 52px; }
.msg__footer { margin-top: 24px; padding-bottom: 8px; }
.msg__buttons { display: flex; flex-wrap: wrap; gap: 8px; }
.smart { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; }
.smart__chip { height: 32px; padding: 0 14px; border: 1px solid var(--border-strong); border-radius: 16px; font-size: 13px; color: var(--text-2); }
.smart__chip:hover { background: var(--hover); }

.details { border-collapse: collapse; font-size: 12px; margin: 10px 12px; max-width: min(460px, 86vw); }
.details th { text-align: right; vertical-align: top; color: var(--text-3); font-weight: 400; padding: 3px 10px 3px 0; white-space: nowrap; }
.details td { padding: 3px 0; word-break: break-word; color: var(--text); }

/* message HTML */
.msg-body { font-size: 14px; line-height: 1.6; color: var(--text); word-break: break-word; overflow-wrap: anywhere; }
.msg-body > :first-child { margin-top: 0; }
.msg-body p { margin: 0 0 12px; }
.msg-body a { color: var(--accent); text-decoration: underline; text-underline-offset: 2px; }
.msg-body img { max-width: 100%; height: auto; border-radius: 8px; }
.msg-body ul, .msg-body ol { margin: 0 0 12px; padding-left: 24px; }
.msg-body li { margin: 2px 0; }
.msg-body h1, .msg-body h2, .msg-body h3 { line-height: 1.3; margin: 16px 0 8px; font-weight: 600; }
.msg-body h1 { font-size: 20px; }
.msg-body h2 { font-size: 17px; }
.msg-body h3 { font-size: 15px; }
.msg-body blockquote { margin: 8px 0 12px 2px; padding: 0 0 0 14px; border-left: 3px solid var(--border-strong); color: var(--text-2); }
.msg-body pre { background: var(--surface-2); border: 1px solid var(--border-soft); border-radius: 8px; padding: 12px 14px; overflow: auto; font-size: 12.5px; line-height: 1.5; }
.msg-body code { background: var(--surface-3); }
.msg-body pre code { background: none; padding: 0; }
.msg-body table { border-collapse: collapse; max-width: 100%; margin: 8px 0 14px; font-size: 13px; }
.msg-body th, .msg-body td { border: 1px solid var(--border); padding: 6px 10px; text-align: left; vertical-align: top; }
.msg-body th { background: var(--surface-2); font-weight: 600; }
.msg-body hr { border: 0; border-top: 1px solid var(--border); margin: 16px 0; }
.msg-body .q { border-left: 3px solid var(--border-strong); margin: 12px 0 0 2px; padding-left: 14px; color: var(--text-2); }
.msg-body .sig { color: var(--text-3); font-size: 13px; margin-top: 16px; }
.msg-body .m-muted { color: var(--text-3); font-size: 13px; }
