success.afterFullFileContent:
.compose-dock {
  position: fixed;
  right: 24px;
  bottom: 0;
  z-index: 80;
  display: flex;
  flex-direction: row-reverse;
  align-items: flex-end;
  gap: 16px;
  pointer-events: none;
  max-width: calc(100vw - 48px);
}
.compose-dock > * { pointer-events: auto; }

.compose {
  display: flex;
  flex-direction: column;
  width: 520px;
  max-width: 94vw;
  height: min(620px, calc(100dvh - 80px));
  background: var(--surface);
  border-radius: 12px 12px 0 0;
  box-shadow: var(--shadow-3);
  border: 1px solid var(--border-soft);
  border-bottom: 0;
  overflow: hidden;
  animation: rise 0.2s;
}
.compose.is-min { height: auto; width: 260px; }
.compose__header {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: none;
  height: 42px;
  padding: 0 6px 0 16px;
  background: var(--compose-head);
  cursor: pointer;
  border-bottom: 1px solid var(--border-soft);
}
.compose__title { flex: 1; min-width: 0; font-size: 14px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.compose__hbtn { width: 30px; height: 30px; }

.compose-overlay { position: fixed; inset: 0; z-index: 90; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, 0.38); animation: fade 0.15s; }
.compose--full { width: min(980px, 94vw); height: min(780px, 92dvh); border-radius: 14px; border-bottom: 1px solid var(--border-soft); }

.compose__form { position: relative; display: flex; flex-direction: column; flex: 1; min-height: 0; background: var(--surface); }
.compose__form.is-dragging::after {
  content: 'Drop files to attach';
  position: absolute;
  inset: 8px;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px dashed var(--accent);
  border-radius: 10px;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface));
  color: var(--on-container);
  font-weight: 600;
}
.compose__fields { flex: none; padding: 0 16px; }
.compose__row { display: flex; align-items: flex-start; border-bottom: 1px solid var(--border-soft); }
.compose__row--to { align-items: flex-start; }
.compose__ccbcc { display: flex; align-items: center; gap: 8px; padding-top: 5px; font-size: 13px; color: var(--text-3); }
.compose__ccbcc button:not(.icon-btn) { padding: 3px 4px; border-radius: 4px; }
.compose__ccbcc button:not(.icon-btn):hover { text-decoration: underline; color: var(--text); }
.compose__subject { width: 100%; height: 40px; border: 0; outline: 0; background: transparent; font-size: 14px; }
.compose__subject::placeholder { color: var(--text-3); }

.rcpt { position: relative; display: flex; align-items: flex-start; flex: 1; min-width: 0; padding: 4px 0; cursor: text; }
.compose__fields > .rcpt { border-bottom: 1px solid var(--border-soft); }
.rcpt__label { flex: none; width: 34px; padding-top: 6px; font-size: 13px; color: var(--text-3); cursor: text; }
.rcpt__chips { flex: 1; display: flex; flex-wrap: wrap; align-items: center; gap: 4px; min-width: 0; }
.rcpt__input { flex: 1 1 80px; min-width: 80px; height: 28px; border: 0; outline: 0; background: transparent; font-size: 14px; }
.rcpt-chip { display: inline-flex; align-items: center; gap: 4px; height: 26px; padding: 0 4px 0 2px; border: 1px solid var(--border); border-radius: 13px; background: var(--surface); font-size: 13px; max-width: 100%; }
.rcpt-chip.is-invalid { border-color: var(--danger); background: var(--danger-soft); }
.rcpt-chip__avatar { display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 20px; border-radius: 50%; color: #fff; font-size: 11px; font-weight: 600; flex: none; }
.rcpt-chip__name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rcpt-chip button { display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 20px; border-radius: 50%; color: var(--text-3); }
.rcpt-chip button:hover { background: var(--hover-strong); }
.rcpt__suggest { position: absolute; left: 30px; top: 100%; z-index: 20; min-width: min(340px, 90%); padding: 6px 0; border-radius: 10px; background: var(--surface); box-shadow: var(--shadow-3); border: 1px solid var(--border-soft); }
.rcpt__opt { display: flex; align-items: center; gap: 10px; padding: 6px 14px; cursor: pointer; }
.rcpt__opt.is-active { background: var(--hover); }
.rcpt__opt-name { font-weight: 500; white-space: nowrap; }
.rcpt__opt-email { color: var(--text-3); font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.compose__body { flex: 1; min-height: 0; overflow-y: auto; padding: 10px 16px 6px; }
.compose__editor { min-height: 140px; outline: 0; font-size: 14px; line-height: 1.6; word-break: break-word; }
.compose__editor a { color: var(--accent); }
.compose__editor blockquote { margin: 8px 0; padding-left: 12px; border-left: 3px solid var(--border-strong); color: var(--text-2); }
.compose__editor ul, .compose__editor ol { padding-left: 24px; }
.compose__quote { margin-top: 6px; }
.compose__attachments { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.compose__footer { display: flex; align-items: center; gap: 2px; flex: none; padding: 8px 10px 12px 16px; }
.compose__tools { display: flex; align-items: center; margin-left: 8px; }
.compose__spacer { flex: 1; }
.compose__saved { font-size: 12px; color: var(--text-3); margin-right: 4px; white-space: nowrap; }

.send-split { display: inline-flex; flex: none; border-radius: 18px; background: var(--accent); color: var(--on-accent); overflow: hidden; }
.send-split__main { height: 36px; padding: 0 20px 0 22px; font-weight: 600; }
.send-split__caret { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 36px; border-left: 1px solid color-mix(in srgb, var(--on-accent) 30%, transparent); }
.send-split__main:hover, .send-split__caret:hover { background: color-mix(in srgb, var(--on-accent) 14%, transparent); }

.fmtbar { display: flex; flex-wrap: wrap; align-items: center; gap: 0; flex: none; padding: 4px 12px; border-top: 1px solid var(--border-soft); background: var(--surface-2); }
.fmtbar .icon-btn { width: 30px; height: 30px; }
.fmtbar__select { height: 28px; padding: 0 4px; border: 0; background: transparent; font-size: 13px; }
.fmtbar .toolbar__sep { margin: 0 4px; height: 18px; }

.reply-to-line { display: flex; align-items: center; gap: 8px; padding: 6px 8px 6px 12px; border-bottom: 1px solid var(--border-soft); }
.reply-to-line__btn { display: inline-flex; align-items: center; gap: 8px; max-width: 100%; padding: 4px 8px; border-radius: 8px; color: var(--text-2); font-size: 13px; min-width: 0; }
.reply-to-line__btn > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.reply-to-line__btn:hover { background: var(--hover); }
.reply-to-line__cc { font-size: 12px; color: var(--text-3); }
.reply-to-line__pop { margin-left: auto; }

.compose__form--inline { border: 1px solid var(--border-strong); border-radius: 16px; overflow: hidden; box-shadow: var(--shadow-1); }
.compose__form--inline .compose__body { max-height: 46vh; }
.compose__form--inline .compose__editor { min-height: 96px; }
.compose__form--inline .compose__fields { padding: 0 12px; }

.link-form { display: flex; flex-direction: column; gap: 10px; width: 290px; max-width: 86vw; padding: 14px; }
.link-form label { display: flex; flex-direction: column; gap: 4px; font-size: 12px; color: var(--text-3); }
.link-form input { height: 36px; padding: 0 10px; border: 1px solid var(--border-strong); border-radius: 8px; background: transparent; font-size: 14px; color: var(--text); }
.link-form input:focus { border-color: var(--accent); outline: 1px solid var(--accent); }
.emoji-grid { display: grid; grid-template-columns: repeat(8, 34px); gap: 2px; padding: 8px; }
.emoji-grid button { width: 34px; height: 34px; border-radius: 8px; font-size: 19px; }
.emoji-grid button:hover { background: var(--hover-strong); }

@media (max-width: 700px) {
  .compose-dock { right: 0; left: 0; max-width: none; display: block; }
  .compose,
  .compose.is-min {
    position: fixed;
    inset: 0;
    width: 100%;
    max-width: none;
    height: 100dvh;
    border-radius: 0;
    border: 0;
    z-index: 120;
    animation: rise 0.22s;
  }
  .compose__header { height: 56px; padding-left: 16px; }
  .compose__hbtn { width: 40px; height: 40px; }
  .compose__form--inline { border-radius: 14px; }
  .compose__footer { flex-wrap: wrap; row-gap: 4px; padding: 8px 8px 12px 12px; }
  .compose__saved { display: none; }
  .compose__editor { min-height: 200px; }
  .rcpt__suggest { left: 0; right: 0; min-width: 0; }
}

args.streamContent:
/* ------------------------------------------------------------ popovers and menus */

.popover {
  position: fixed;
  z-index: 260;
  max-width: calc(100vw - 16px);
  max-height: calc(100dvh - 16px);
  overflow: auto;
  background: var(--surface);
  border: 1px solid var(--border-soft);
  border-radius: 10px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.16), 0 10px 28px rgba(0, 0, 0, 0.2);
  animation: pop 0.1s ease-out;
}
:root[data-theme='dark'] .popover { border-color: var(--border); }
.popover--account { border-radius: 24px; }
.popover--snooze { width: 264px; }
.popover--labels { width: 268px; }
.menu { padding: 8px 0; min-width: 200px; }
.menu__item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 34px;
  padding: 0 18px 0 12px;
  font-size: 13.5px;
  text-align: left;
  white-space: nowrap;
}
.menu__item:hover:not(:disabled),
.menu__item:focus-visible { background: var(--hover); outline: 0; }
.menu__item:disabled { opacity: 0.42; }
.menu__item.is-danger { color: var(--danger); }
.menu__check { display: inline-flex; align-items: center; justify-content: center; width: 20px; flex: none; color: var(--text-3); }
.menu__label { flex: 1; }
.menu__hint { color: var(--text-3); font-size: 12px; padding-left: 20px; }
.menu__chev { color: var(--text-3); margin-right: -6px; }
.menu__header { padding: 6px 16px 6px; font-size: 12px; font-weight: 600; color: var(--text-3); }
.menu__divider { height: 1px; margin: 6px 0; background: var(--border-soft); }

.snooze-custom { display: flex; flex-direction: column; gap: 10px; padding: 8px 0 12px; }
.snooze-custom input { margin: 0 14px; height: 38px; padding: 0 10px; border: 1px solid var(--border-strong); border-radius: 8px; background: transparent; color: var(--text); }
.snooze-custom input:focus { border-color: var(--accent); outline: 1px solid var(--accent); }
.snooze-custom__actions { display: flex; justify-content: flex-end; gap: 8px; padding: 0 12px; }

.label-menu { padding: 8px 0; }
.label-menu__search { width: calc(100% - 24px); margin: 2px 12px 8px; height: 34px; padding: 0 10px; border: 1px solid var(--border-strong); border-radius: 8px; background: transparent; }
.label-menu__search:focus { border-color: var(--accent); outline: 1px solid var(--accent); }
.label-menu__list { max-height: 220px; overflow: auto; }
.label-menu__item { display: flex; align-items: center; gap: 12px; width: 100%; height: 34px; padding: 0 16px; font-size: 13.5px; text-align: left; }
.label-menu__item:hover { background: var(--hover); }
.label-menu__dot { width: 10px; height: 10px; border-radius: 50%; flex: none; }
.label-menu__empty { padding: 10px 16px; font-size: 13px; color: var(--text-3); }

/* ------------------------------------------------------------ toasts */

.toasts { position: fixed; left: 16px; bottom: 16px; z-index: 380; display: flex; flex-direction: column; align-items: flex-start; gap: 8px; pointer-events: none; }
.toast {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 4px;
  min-height: 48px;
  max-width: min(560px, calc(100vw - 32px));
  padding: 4px 6px 4px 18px;
  border-radius: 8px;
  background: var(--toast-bg);
  color: var(--toast-fg);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.35);
  font-size: 14px;
  animation: toast-in 0.2s ease-out;
}
.toast__text { flex: 1; padding: 6px 12px 6px 0; }
.toast__action { height: 34px; padding: 0 12px; border-radius: 17px; color: var(--toast-action); font-weight: 600; white-space: nowrap; }
.toast__action:hover { background: color-mix(in srgb, var(--toast-fg) 12%, transparent); }
.toast__close { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px; border-radius: 50%; opacity: 0.75; }
.toast__close:hover { opacity: 1; background: color-mix(in srgb, var(--toast-fg) 12%, transparent); }

/* ------------------------------------------------------------ modals */

.modal-scrim { position: fixed; inset: 0; z-index: 330; display: flex; align-items: center; justify-content: center; padding: 16px; background: rgba(0, 0, 0, 0.46); animation: fade 0.15s; }
.modal { width: min(440px, 100%); max-height: 92dvh; overflow: auto; padding: 24px; border-radius: 28px; background: var(--surface); box-shadow: var(--shadow-3); animation: pop 0.16s ease-out; }
.modal--wide { width: min(900px, 100%); }
.modal__head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.modal__title { font-size: 22px; font-weight: 400; margin-bottom: 12px; }
.modal__head .modal__title { margin-bottom: 0; }
.modal__body { color: var(--text-2); line-height: 1.55; }
.modal__actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 24px; }

.field { display: flex; flex-direction: column; gap: 6px; margin-bottom: 18px; font-size: 13px; color: var(--text-2); }
.field input { height: 46px; padding: 0 14px; border: 1px solid var(--border-strong); border-radius: 8px; background: transparent; font-size: 15px; color: var(--text); }
.field input:focus { border-color: var(--accent); outline: 1px solid var(--accent); }
.field input[aria-invalid='true'] { border-color: var(--danger); outline-color: var(--danger); }
.field__error { color: var(--danger); font-style: normal; font-size: 12px; }
.swatches { display: flex; flex-wrap: wrap; gap: 10px; }
.swatch { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; border-radius: 50%; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.12); }
.swatch.is-on { outline: 2px solid var(--text-2); outline-offset: 2px; }
.swatches--inline { padding: 8px 0 4px 26px; }

.shortcuts { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 24px 44px; margin-top: 16px; }
.shortcuts h3 { font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-3); margin-bottom: 8px; }
.shortcuts dl { margin: 0; }
.shortcuts__row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 6px 0; border-bottom: 1px solid var(--border-soft); font-size: 13px; }
.shortcuts__row dt { display: flex; align-items: center; flex-wrap: wrap; gap: 4px; order: 2; flex: none; }
.shortcuts__row dd { margin: 0; order: 1; color: var(--text-2); }
.shortcuts__sep { font-size: 11px; color: var(--text-3); }

/* ------------------------------------------------------------ quick settings */

.qs-scrim { position: fixed; inset: 0; z-index: 150; }
.qs { position: fixed; top: 0; right: 0; bottom: 0; z-index: 160; display: flex; flex-direction: column; width: min(368px, 100%); background: var(--surface); box-shadow: -4px 0 28px rgba(0, 0, 0, 0.22); border-left: 1px solid var(--border-soft); animation: slide-in 0.22s cubic-bezier(0.2, 0.8, 0.2, 1); }
.qs__head { display: flex; align-items: center; justify-content: space-between; height: 64px; padding: 0 12px 0 24px; flex: none; }
.qs__head h2 { font-size: 18px; font-weight: 500; }
.qs__body { flex: 1; overflow: auto; padding: 4px 24px 32px; }
.qs__body > .btn { margin-bottom: 24px; }
.qs-section { margin-bottom: 26px; }
.qs-section h3 { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-3); margin-bottom: 10px; }
.theme-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.theme-card { display: flex; flex-direction: column; gap: 8px; padding: 6px; border: 2px solid var(--border); border-radius: 12px; }
.theme-card:hover { background: var(--hover); }
.theme-card.is-on { border-color: var(--accent); background: var(--accent-soft); }
.theme-card__preview { display: grid; grid-template-columns: 14px 1fr; grid-template-rows: 1fr 1fr; gap: 3px; height: 48px; padding: 4px; border-radius: 6px; background: #f6f8fc; }
.theme-card__preview i { border-radius: 3px; background: #fff; }
.theme-card__preview i:nth-child(1) { grid-row: 1 / 3; background: #d3e3fd; }
.theme-card--dark .theme-card__preview { background: #0d0f12; }
.theme-card--dark .theme-card__preview i { background: #1d2025; }
.theme-card--dark .theme-card__preview i:nth-child(1) { background: #2b3a55; }
.theme-card--system .theme-card__preview { background: linear-gradient(90deg, #f6f8fc 50%, #0d0f12 50%); }
.theme-card--system .theme-card__preview i:nth-child(2) { background: linear-gradient(90deg, #fff 50%, #1d2025 50%); }
.theme-card--system .theme-card__preview i:nth-child(3) { background: linear-gradient(90deg, #fff 50%, #1d2025 50%); }
.theme-card--system .theme-card__preview i:nth-child(1) { background: linear-gradient(90deg, #d3e3fd 50%, #2b3a55 50%); }
.theme-card__label { display: flex; align-items: center; justify-content: center; gap: 6px; font-size: 13px; font-weight: 500; padding-bottom: 2px; }
.accent-row { display: flex; gap: 12px; margin-top: 16px; }
.accent-dot { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px; border-radius: 50%; }
.accent-dot.is-on { box-shadow: 0 0 0 2px var(--surface), 0 0 0 4px var(--text-3); }
.radio-list { display: flex; flex-direction: column; gap: 2px; }
.radio-card { display: flex; align-items: flex-start; gap: 14px; padding: 10px 8px; border-radius: 12px; text-align: left; }
.radio-card:hover { background: var(--hover); }
.radio-card__dot { display: inline-flex; align-items: center; justify-content: center; flex: none; width: 20px; height: 20px; margin-top: 1px; border: 2px solid var(--text-3); border-radius: 50%; }
