.setting__desc { margin-top: 2px; max-width: 520px; font-size: 13px; color: var(--text-3); line-height: 1.5; }
.setting__control { flex: none; display: flex; align-items: center; }
.seg { display: inline-flex; border: 1px solid var(--border-strong); border-radius: 18px; overflow: hidden; }
.seg button { height: 34px; padding: 0 18px; font-weight: 500; }
.seg button:hover { background: var(--hover); }
.seg button.is-on { background: var(--accent-container); color: var(--on-container); }
.settings__toolbar { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 0; color: var(--text-3); font-size: 13px; }
.label-table { width: 100%; border-collapse: collapse; }
.label-table th { text-align: left; font-size: 12px; font-weight: 600; color: var(--text-3); padding: 8px; border-bottom: 1px solid var(--border); }
.label-table td { padding: 8px; border-bottom: 1px solid var(--border-soft); vertical-align: middle; }
.label-table__name { display: flex; align-items: center; gap: 12px; }
.label-table__name input { flex: 1; min-width: 0; height: 34px; padding: 0 8px; border: 1px solid transparent; border-radius: 6px; background: transparent; font-size: 14px; }
.label-table__name input:hover { border-color: var(--border); }
.label-table__name input:focus { border-color: var(--accent); outline: 0; background: var(--surface); }
.label-dot { width: 16px; height: 16px; border-radius: 50%; flex: none; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.12); }
.signature-editor { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; padding-top: 16px; }
.signature-editor textarea { min-height: 120px; padding: 12px; border: 1px solid var(--border-strong); border-radius: 10px; background: transparent; resize: vertical; line-height: 1.5; }
.signature-editor textarea:focus { border-color: var(--accent); outline: 1px solid var(--accent); }
.signature-editor textarea:disabled { opacity: 0.5; }
.signature-preview { padding: 12px 14px; border: 1px dashed var(--border-strong); border-radius: 10px; font-size: 14px; line-height: 1.55; color: var(--text-2); }

@media (max-width: 700px) {
  .toasts { left: 8px; right: 8px; bottom: 84px; }
  .toast { max-width: none; width: 100%; }
  .settings { padding: 0 16px 40px; }
  .setting { align-items: flex-start; flex-direction: column; gap: 10px; }
  .signature-editor { grid-template-columns: 1fr; }
  .modal { padding: 20px; border-radius: 24px; }
  .qs { width: 100%; }
  .label-table th:nth-child(2), .label-table td:nth-child(2) { display: none; }
}

/* ------------------------------------------------------------ print */

@media print {
  body { overflow: visible; background: #fff; }
  .header, .sidebar, .toolbar, .compose-dock, .toasts, .fab, .scrim, .msg__footer, .thread__reply, .msg__tools, .thread__head-actions, .banner { display: none !important; }
  .app, .app__body, .main, .panel, .thread, .thread__scroll { display: block !important; height: auto !important; overflow: visible !important; border-radius: 0 !important; padding: 0 !important; }
  .msg__content { padding-left: 0; }
}

