import { chromium } from 'playwright';
const browser = await chromium.launch({ channel: 'chrome' });
const BASE = 'http://127.0.0.1:9369';
for (const [w, h, mobile] of [[1440, 900, false], [390, 844, true], [1024, 768, false]]) {
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, isMobile: mobile, hasTouch: mobile });
  const p = await ctx.newPage();
  await p.goto(BASE + '/#/inbox');
  await p.waitForSelector('.row');
  const info = await p.evaluate(() => {
    const r = (s) => { const e = document.querySelector(s); if (!e) return null; const b = e.getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height) }; };
    const rows = [...document.querySelectorAll('.row')].slice(0, 6).map((row) => {
      const g = (s) => { const e = row.querySelector(s); if (!e) return null; const b = e.getBoundingClientRect(); return [Math.round(b.x), Math.round(b.width)]; };
      return { h: Math.round(row.getBoundingClientRect().height), sender: g('.row__sender'), subject: g('.row__subject'), snippet: g('.row__snippet'), meta: g('.row__meta') };
    });
    return { title: r('.brand__title'), search: r('.header__search'), right: r('.header__right'), sidebar: r('.sidebar'), main: r('.main'), panel: r('.panel'), rows, hs: document.documentElement.scrollWidth };
  });
  console.log(w, JSON.stringify(info, null, 1));
  await ctx.close();
}
await browser.close();
EOF
